"""Every source module that defines a public name states its public surface with ``__all__``.

The package ships ``py.typed``, so for a type checker ``__all__`` decides which names a consumer may
import. A module without one, or one that lists a name it no longer defines, drifts unnoticed.
"""

from __future__ import annotations

import ast
from pathlib import Path

import pytest

from tests.support.os_markers import os_agnostic

SOURCE_ROOT = Path(__file__).resolve().parents[2] / "src" / "lib_layered_config"

#: Generated by bmk from pyproject.toml, or a ``python -m`` entry point with nothing to export.
SKIPPED = {"__init__conf__.py", "__main__.py"}

#: Names public by spelling only, each with its reason.
NOT_EXPORTED = {
    # The lazily imported PyYAML module object: module state, not API.
    ("adapters/file_loaders/structured.py", "yaml"),
    # A security ceiling kept internal on purpose (CLAUDE.md, Profile Name Validation).
    ("domain/identifiers.py", "ABSOLUTE_MAX_PROFILE_LENGTH"),
    # A TypeVar for the signatures of Config.get; never imported by a caller.
    ("domain/config.py", "T"),
}


def _modules() -> list[Path]:
    return sorted(path for path in SOURCE_ROOT.rglob("*.py") if path.name not in SKIPPED)


def _module_id(path: Path) -> str:
    return path.relative_to(SOURCE_ROOT).as_posix()


def _assigned_names(node: ast.stmt) -> list[str]:
    targets = node.targets if isinstance(node, ast.Assign) else [node.target] if isinstance(node, ast.AnnAssign) else []
    return [target.id for target in targets if isinstance(target, ast.Name)]


def _defined_public_names(tree: ast.Module, module: str) -> set[str]:
    names: set[str] = set()
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
        names.update(_assigned_names(node))
    return {name for name in names if not name.startswith("_") and (module, name) not in NOT_EXPORTED}


def _declared_all(tree: ast.Module) -> list[str] | None:
    for node in tree.body:
        if "__all__" in _assigned_names(node):
            value = node.value
            assert isinstance(value, (ast.List, ast.Tuple)), "__all__ must be a literal list or tuple"
            return [ast.literal_eval(element) for element in value.elts]
    return None


@os_agnostic
@pytest.mark.parametrize("path", _modules(), ids=_module_id)
def test_a_module_defining_public_names_lists_them_in_all(path: Path) -> None:
    module = _module_id(path)
    tree = ast.parse(path.read_text(encoding="utf-8"))
    declared = _declared_all(tree)
    defined = _defined_public_names(tree, module)

    if declared is None:
        assert not defined, f"{module} defines {sorted(defined)} but has no __all__"
        return
    # A facade (a package __init__, core.py) re-exports names it imports.
    imported = {
        alias.asname or alias.name for node in tree.body if isinstance(node, ast.ImportFrom) for alias in node.names
    }
    assert set(declared) <= defined | imported, f"{module} lists names it neither defines nor imports"
    if path.name != "__init__.py":
        assert defined <= set(declared), f"{module} defines {sorted(defined - set(declared))} outside __all__"


@os_agnostic
def test_the_scan_sees_the_modules() -> None:
    """A wrong root would pass every case above by collecting none."""
    assert len(_modules()) > 40
